import vento from "ventojs";
import { normalizePath } from "../core/utils/path.js";
import { formatBytes } from "./std.js";
const env = vento({
    includes: import.meta.resolve("../core/templates"),
});
export async function render(file, data = {}) {
    try {
        return (await env.run(file, data)).content;
    }
    catch (err) {
        console.log(err);
        throw err;
    }
}
// deno-lint-ignore no-explicit-any
export function filter(name, filter) {
    env.filters[name] = filter;
}
filter("formatBytes", formatBytes);
filter("normalizePath", (args) => normalizePath(...args));
